[
  {
    "title": "預檢請求的觸發時機",
    "body": "跨來源請求若可能改變伺服器狀態，或帶有自訂標頭，瀏覽器會先發送預檢請求。",
    "examples": [
      "跨來源 DELETE /users/42",
      "跨來源請求帶有 X-Client-Version: 2"
    ],
    "lines": [6, 9]
  },
  {
    "title": "預檢通過後才送正式請求",
    "body": "伺服器同意預檢後，瀏覽器才會送出真正請求，以保護未預期跨來源寫入的舊系統。",
    "examples": [
      "伺服器回覆 Access-Control-Allow-Origin 後，瀏覽器才送出 POST"
    ],
    "lines": [11, 12]
  },
  {
    "title": "預檢結果快取",
    "body": "預檢結果可快取一段時間，讓後續符合條件的請求免除重複往返。",
    "examples": [
      "伺服器設定 Access-Control-Max-Age: 600"
    ],
    "lines": [14, 14]
  }
]
